parameters.jsCode:
const cart = $('Obtener Carrito').first().json;
const addResp = $('Agregar Item').first().json;
const sum = $input.first().json;

if (!addResp || addResp.status >= 400) {
  return [{ json: { ok: false, error: addResp?.message || 'Error al agregar' } }];
}

const d = sum?.data || {};
const h = d.header || {};

// Items REALES del carrito (ya ordenados: cada BONUS va tras su SALE de origen).
// El agente debe mostrar EXACTAMENTE estos; no inventar lineas de bonus/descuento.
const items = (d.items || []).map(i => {
  const qty = Number(i.quantity);
  const up = Number(i.unitPrice);
  const lt = Number(i.lineTotal);
  const sub = Math.round(qty * up * 100) / 100;
  const desc = (i.lineType === 'SALE') ? Math.round((sub - lt) * 100) / 100 : 0;
  const pct = (i.lineType === 'SALE' && sub > 0 && desc > 0) ? Math.round(desc / sub * 100) : 0;
  return { sku: i.productCode, nombre: i.productName, qty, unit_price: up, line_subtotal: sub, line_total: lt, descuento: desc, descuento_pct: pct, tipo: i.lineType };
});

return [{ json: {
  ok: true,
  cart_id: cart?.data?.cart_id || null,
  line_id: addResp?.data?.line_id || null,
  subtotal: Number(h.subtotal || 0),
  descuento: Number(h.discount || 0),
  total: Number(h.total || 0),
  items
} }];
